function defaultTimer(){return{phase:'work',round_count:0,running:false,ends_at:null,remaining_seconds:TIMER_DURATIONS.work}}
function normalizeTimer(row){if(!row)return defaultTimer();const phase=TIMER_DURATIONS[row.phase]?row.phase:'work',duration=TIMER_DURATIONS[phase];return{phase,round_count:Math.max(0,Math.min(3,Number(row.round_count)||0)),running:!!row.running,ends_at:row.ends_at||null,remaining_seconds:Math.max(0,Math.min(7200,Number(row.remaining_seconds)||duration))}}
