function renderTimer(){const panel=document.getElementById('missionTimer');if(!panel)return;const remaining=timerRemaining(),duration=TIMER_DURATIONS[focusTimer.phase],progress=Math.max(0,Math.min(100,(1-remaining/duration)*100));panel.style.setProperty('--timer-progress',`${progress}%`);panel.classList.toggle('running',focusTimer.running);panel.classList.toggle('break-mode',focusTimer.phase!=='work');panel.classList.toggle('danger',focusTimer.running&&focusTimer.phase==='work'&&remaining<=60);document.getElementById('timerPhase').textContent=timerLabel();document.getElementById('timerHint').textContent=timerHint();document.getElementById('timerDisplay').textContent=formatTimer(remaining);document.getElementById('bombClock').setAttribute('aria-label',`${timerLabel()} ${formatTimer(remaining)}`);document.getElementById('timerStartPause').textContent=focusTimer.running?'Ⅱ 暫停':focusTimer.phase==='work'?'▶ 開始任務':'▶ 繼續休息';const completed=focusTimer.phase==='long_break'?4:focusTimer.round_count;document.getElementById('timerRounds').innerHTML=Array.from({length:4},(_,i)=>`<span class="timer-round ${i<completed?'complete':''} ${focusTimer.phase==='work'&&i===focusTimer.round_count?'current':''}" title="第 ${i+1} 組"></span>`).join('')}
async function persistTimer(){if(!session)return;const row={user_id:session.user.id,phase:focusTimer.phase,round_count:focusTimer.round_count,running:focusTimer.running,ends_at:focusTimer.ends_at,remaining_seconds:timerRemaining(),updated_at:new Date().toISOString()};const {error}=await db.from('focus_timers').upsert(row);if(error){console.error(error);showToast('計時器同步失敗，請再試一次',true)}return error}
function armTimerSound(){try{audioContext??=new(window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume()}catch(_error){}}
function playTimerSound(){if(!audioContext||audioContext.state!=='running')return;[0,.18,.36].forEach((delay,index)=>{const oscillator=audioContext.createOscillator(),gain=audioContext.createGain(),time=audioContext.currentTime+delay;oscillator.type='sine';oscillator.frequency.setValueAtTime(index===2?880:660,time);gain.gain.setValueAtTime(.0001,time);gain.gain.exponentialRampToValueAtTime(.14,time+.02);gain.gain.exponentialRampToValueAtTime(.0001,time+.14);oscillator.connect(gain).connect(audioContext.destination);oscillator.start(time);oscillator.stop(time+.16)})}
async function advanceTimer(){if(timerTransitioning||!focusTimer.running||!focusTimer.ends_at)return;timerTransitioning=true;let endTime=new Date(focusTimer.ends_at).getTime(),now=Date.now(),changed=false;for(let transitions=0;now>=endTime&&transitions<24;transitions++){changed=true;if(focusTimer.phase==='work'){const completed=focusTimer.round_count+1;if(completed>=4){focusTimer.phase='long_break';focusTimer.round_count=0}else{focusTimer.phase='short_break';focusTimer.round_count=completed}}else{focusTimer.phase='work'}focusTimer.remaining_seconds=TIMER_DURATIONS[focusTimer.phase];endTime+=focusTimer.remaining_seconds*1000}if(changed){focusTimer.ends_at=new Date(endTime).toISOString();focusTimer.remaining_seconds=Math.max(0,Math.ceil((endTime-now)/1000));renderTimer();playTimerSound();showToast(focusTimer.phase==='work'?'休息結束，下一組任務開始！':focusTimer.phase==='long_break'?'四組達成！進入 30 分鐘長休息':'拆彈成功！自動開始 10 分鐘休息');await persistTimer()}timerTransitioning=false}
