function missionsFor(date,{includeDeleted=false}={}){const built=baseMissions(date).map(q=>{const o=overrides[q.id]||{};return{...q,subject:o.subject??q.subject,name:o.task_name??q.name,time:o.task_time??q.time,clear:o.clear_condition??q.clear,xp:o.xp??q.xp,completed:!!o.completed,deleted:!!o.deleted,quadrant:o.quadrant||suggestedQuadrant(q,date)}});const custom=customQuests.filter(q=>q.date===iso(date));return[...built,...custom].filter(q=>includeDeleted||!q.deleted)}
