function clearDragUi(){document.querySelectorAll('.drag-over,.dragging,.drag-source').forEach(el=>el.classList.remove('drag-over','dragging','drag-source'));dragState?.ghost?.remove();dragState=null;document.onpointermove=null;document.onpointerup=null;document.onpointercancel=null}
function markDropTarget(x,y){document.querySelectorAll('.quadrant').forEach(el=>el.classList.remove('drag-over'));const target=document.elementFromPoint(x,y)?.closest('.quadrant[data-quadrant]');target?.classList.add('drag-over');return target}
function startTouchDrag(card,id,event){clearDragUi();const rect=card.getBoundingClientRect(),ghost=card.cloneNode(true);ghost.className='quest drag-ghost';ghost.removeAttribute('draggable');ghost.style.width=`${Math.min(rect.width,420)}px`;document.body.appendChild(ghost);card.classList.add('drag-source');dragState={id,ghost};const move=e=>{ghost.style.left=`${Math.min(e.clientX+12,window.innerWidth-ghost.offsetWidth-8)}px`;ghost.style.top=`${Math.min(e.clientY+12,window.innerHeight-ghost.offsetHeight-8)}px`;markDropTarget(e.clientX,e.clientY)};move(event);document.onpointermove=e=>{e.preventDefault();move(e)};document.onpointerup=e=>{const target=markDropTarget(e.clientX,e.clientY),quadrant=target?.dataset.quadrant,taskId=dragState?.id;clearDragUi();if(taskId&&quadrant)moveTask(taskId,quadrant)};document.onpointercancel=clearDragUi}
function wireTaskCards(){document.querySelectorAll('[data-check]').forEach(el=>el.addEventListener('change',()=>toggleTask(el.dataset.check,el.checked)));document.querySelectorAll('[data-delete]').forEach(el=>el.addEventListener('click',()=>deleteTask(el.dataset.delete)));document.querySelectorAll('[data-edit]').forEach(el=>el.addEventListener('click',()=>openTaskEditor(el.dataset.edit)));document.querySelectorAll('.quest').forEach(card=>{card.addEventListener('dragstart',event=>{if(event.target.closest('button:not(.drag-handle),input')){event.preventDefault();return}dragState={id:card.dataset.task};card.classList.add('dragging');event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',card.dataset.task)});card.addEventListener('dragend',clearDragUi);card.querySelector('.drag-handle').addEventListener('pointerdown',event=>{if(event.pointerType!=='mouse'){event.preventDefault();startTouchDrag(card,card.dataset.task,event)}})});document.querySelectorAll('.quadrant[data-quadrant]').forEach(zone=>{zone.addEventListener('dragover',event=>{event.preventDefault();event.dataTransfer.dropEffect='move';document.querySelectorAll('.quadrant').forEach(el=>el.classList.toggle('drag-over',el===zone))});zone.addEventListener('dragleave',event=>{if(!zone.contains(event.relatedTarget))zone.classList.remove('drag-over')});zone.addEventListener('drop',event=>{event.preventDefault();const id=event.dataTransfer.getData('text/plain')||dragState?.id,quadrant=zone.dataset.quadrant;clearDragUi();if(id&&quadrant)moveTask(id,quadrant)})})}
async function moveTask(id,quadrant){if(!quadrants.some(x=>x[0]===quadrant))return;const q=findTask(id);if(!q||q.quadrant===quadrant)return;const previous=q.quadrant;q.quadrant=quadrant;if(!q.custom)overrides[q.id]={...(overrides[q.id]||{}),quadrant};render();setSyncing(true);let error;if(q.custom){({error}=await db.from('custom_tasks').update({quadrant,updated_at:new Date().toISOString()}).eq('id',q.id).eq('user_id',session.user.id))}else{({error}=await db.from('task_overrides').upsert(fixedOverrideRow(q,{quadrant})))}setSyncing(false);if(error){q.quadrant=previous;if(!q.custom)overrides[q.id]={...(overrides[q.id]||{}),quadrant:previous};render();showToast('分類移動失敗，請再試一次',true);return}showToast('任務分類已更新')}
function openTaskCreator(){const form=document.getElementById('customQuestForm');editingTaskId=null;form.reset();form.elements.editId.value='';document.getElementById('questDialogTitle').textContent='建立自訂關卡';document.getElementById('customQuestDate').textContent=`${selected.toLocaleDateString('zh-TW',{month:'long',day:'numeric',weekday:'long'})}的新任務`;document.getElementById('questSubmitButton').textContent='加入今日任務';document.getElementById('questDialog').showModal()}
function openTaskEditor(id){const q=findTask(id);if(!q)return;const form=document.getElementById('customQuestForm');editingTaskId=id;form.elements.editId.value=id;form.elements.subject.value=q.subject;form.elements.time.value=(q.time||'19:00').split('–')[0];form.elements.name.value=q.name;form.elements.clear.value=q.clear;form.elements.xp.value=String(q.xp);form.elements.quadrant.value=q.quadrant;document.getElementById('questDialogTitle').textContent='編輯任務';document.getElementById('customQuestDate').textContent=`${selected.toLocaleDateString('zh-TW',{month:'long',day:'numeric',weekday:'long'})}・修改後自動同步`;document.getElementById('questSubmitButton').textContent='儲存修改';document.getElementById('questDialog').showModal()}
async function toggleTask(id,value){const q=findTask(id);if(!q)return;const oldLevel=totals().level,previous=q.completed;q.completed=value;if(!q.custom)overrides[q.id]={...(overrides[q.id]||{}),completed:value};render();setSyncing(true);let error;if(q.custom){({error}=await db.from('custom_tasks').update({completed:value,updated_at:new Date().toISOString()}).eq('id',q.id).eq('user_id',session.user.id))}else{({error}=await db.from('task_overrides').upsert(fixedOverrideRow(q,{completed:value})))}setSyncing(false);if(error){q.completed=previous;if(!q.custom)overrides[q.id]={...(overrides[q.id]||{}),completed:previous};showToast('同步失敗，請再試一次',true);render();return}const newLevel=totals().level;if(value){burst();showToast(newLevel>oldLevel?`升級！你現在是 Level ${newLevel}`:'任務完成，XP 已存檔')}}
async function deleteTask(id){const q=findTask(id);if(!q)return;setSyncing(true);let error;if(q.custom){({error}=await db.from('custom_tasks').delete().eq('id',q.id).eq('user_id',session.user.id));if(!error)customQuests=customQuests.filter(x=>x.id!==q.id)}else{const current=overrides[q.id]||{};({error}=await db.from('task_overrides').upsert(fixedOverrideRow(q,{deleted:true})));if(!error)overrides[q.id]={...current,deleted:true,quadrant:current.quadrant||q.quadrant}}setSyncing(false);if(error){showToast('刪除失敗，請再試一次',true);return}render();showToast('關卡已刪除')}
function renderSchedule(){document.getElementById('scheduleList').innerHTML=Array.from({length:7},(_,i)=>add(selected,i)).filter(d=>d<=end).map(d=>{const qs=missionsFor(d),dn=qs.filter(q=>q.completed).length;return`<article class="schedule-day ${iso(d)===iso(selected)?'today':''}"><b>${d.toLocaleDateString('zh-TW',{month:'numeric',day:'numeric',weekday:'short'})}</b><div>${qs.slice(0,2).map(q=>esc(q.subject)+'・'+esc(q.name)).join('<br>')||'自由安排'}</div><div class="day-count">${dn}/${qs.length}</div></article>`}).join('')}
function renderStats(){const t=totals(),rate=t.all.length?Math.round(t.done.length/t.all.length*100):0;document.getElementById('totalXpStat').textContent=`${t.xp} XP`;document.getElementById('doneStat').textContent=`${t.done.length} 關`;document.getElementById('rateStat').textContent=`${rate}%`;const achievements=[['第一步',1],['十連擊',10],['百關英雄',100],['Level 5',2000]];document.getElementById('achievements').innerHTML=achievements.map(([name,need],i)=>{const unlocked=i<3?t.done.length>=need:t.xp>=need;return`<div class="achievement ${unlocked?'':'locked'}"><div class="badge">${unlocked?'✓':'?'}</div><div><b>${name}</b><div class="small">${i<3?`完成 ${need} 關`:`累積 ${need} XP`}</div></div></div>`}).join('')}
async function loadUserData(){setSyncing(true);const uid=session.user.id;const [p,c,o,timer]=await Promise.all([db.from('profiles').select('*').eq('user_id',uid).maybeSingle(),db.from('custom_tasks').select('*').eq('user_id',uid).order('created_at'),db.from('task_overrides').select('*').eq('user_id',uid),db.from('focus_timers').select('*').eq('user_id',uid).maybeSingle()]);const firstError=p.error||c.error||o.error||timer.error;if(firstError)throw firstError;if(!p.data){const display=session.user.user_metadata?.full_name||session.user.user_metadata?.name||session.user.email?.split('@')[0]||'玩家';const created=await db.from('profiles').insert({user_id:uid,display_name:display,headline:profile.headline,theme:'pink'}).select().single();if(created.error)throw created.error;profile=created.data}else profile=p.data;customQuests=(c.data||[]).map(normalizeCustom);overrides=Object.fromEntries((o.data||[]).map(x=>[x.task_key,x]));focusTimer=normalizeTimer(timer.data);if(!timer.data){const {error}=await db.from('focus_timers').insert({user_id:uid,...focusTimer});if(error)throw error}setSyncing(false)}
function updateAccountUi(){const user=session.user,display=profile.display_name||user.user_metadata?.full_name||user.email?.split('@')[0]||'玩家',avatar=user.user_metadata?.avatar_url;document.getElementById('accountName').textContent=display;document.getElementById('accountAvatar').innerHTML=avatar?`<img class="avatar" alt="" src="${esc(avatar)}">`:`<span class="avatar">${esc(display[0]||'P')}</span>`;document.getElementById('settingsAvatar').innerHTML=avatar?`<img class="avatar" alt="" src="${esc(avatar)}">`:`<span class="avatar">${esc(display[0]||'P')}</span>`;document.getElementById('settingsName').textContent=display;document.getElementById('settingsEmail').textContent=user.email||''}
async function handleSession(next){if(loadingUser===next?.user?.id)return;session=next||null;if(!session){loadingUser=null;clearInterval(timerInterval);timerInterval=null;document.getElementById('authScreen').classList.remove('hidden');document.getElementById('loadingMask').classList.add('hidden');return}loadingUser=session.user.id;document.getElementById('authScreen').classList.add('hidden');document.getElementById('loadingMask').classList.remove('hidden');try{await loadUserData();updateAccountUi();render();startTimerLoop();if(focusTimer.running&&timerRemaining()<=0)await advanceTimer();document.getElementById('loadingMask').classList.add('hidden')}catch(error){console.error(error);document.getElementById('loadingMask').classList.add('hidden');showToast('資料載入失敗，請重新整理',true)}finally{loadingUser=null}}
async function signIn(){document.getElementById('authError').textContent='';const {error}=await db.auth.signInWithOAuth({provider:'google',options:{redirectTo:SITE_URL,queryParams:{prompt:'select_account'}}});if(error)document.getElementById('authError').textContent='登入沒有成功，請再試一次'}
async function signOut(){await db.auth.signOut();clearInterval(timerInterval);timerInterval=null;profile={headline:'with great power comes great responsibility',theme:'pink',display_name:''};customQuests=[];overrides={};focusTimer=defaultTimer();session=null;document.getElementById('settingsDialog').close();document.getElementById('authScreen').classList.remove('hidden')}
async function switchAccount(){await db.auth.signOut();await signIn()}
function wireUi(){document.getElementById('googleSignIn').onclick=signIn;document.getElementById('accountButton').onclick=()=>{document.getElementById('headlineInput').value=profile.headline;document.querySelector(`input[name="theme"][value="${profile.theme}"]`).checked=true;document.getElementById('settingsDialog').showModal()};document.getElementById('closeSettings').onclick=()=>document.getElementById('settingsDialog').close();document.getElementById('signOutButton').onclick=signOut;document.getElementById('switchAccountButton').onclick=switchAccount;document.getElementById('timerStartPause').onclick=toggleTimer;document.getElementById('timerReset').onclick=resetTimer;document.getElementById('prevDay').onclick=()=>{if(selected>start){selected=add(selected,-1);render()}};document.getElementById('nextDay').onclick=()=>{if(selected<end){selected=add(selected,1);render()}};document.querySelectorAll('.nav-btn').forEach(btn=>btn.onclick=()=>{renderStats();renderSchedule();document.querySelectorAll('.nav-btn,.panel').forEach(x=>x.classList.remove('active'));btn.classList.add('active');document.getElementById(btn.dataset.panel).classList.add('active')});const questDialog=document.getElementById('questDialog'),questForm=document.getElementById('customQuestForm');document.getElementById('openQuestDialog').onclick=openTaskCreator;document.getElementById('cancelQuestDialog').onclick=()=>questDialog.close();questDialog.addEventListener('close',()=>{editingTaskId=null});questForm.addEventListener('submit',saveQuest);document.getElementById('settingsForm').addEventListener('submit',saveSettings)}
async function saveQuest(event){event.preventDefault();const data=new FormData(event.currentTarget),xpRaw=Number(data.get('xp')),values={subject:String(data.get('subject')).trim().slice(0,20),name:String(data.get('name')).trim().slice(0,50),time:String(data.get('time')),clear:String(data.get('clear')).trim().slice(0,80),xp:Number.isFinite(xpRaw)?Math.min(200,Math.max(0,Math.round(xpRaw/5)*5)):30,quadrant:String(data.get('quadrant'))};if(!values.subject||!values.name||!values.clear||!quadrants.some(x=>x[0]===values.quadrant))return;setSyncing(true);if(editingTaskId){const q=findTask(editingTaskId);let error;if(!q){setSyncing(false);showToast('找不到這個任務',true);return}if(q.custom){({error}=await db.from('custom_tasks').update({subject:values.subject,title:values.name,start_time:values.time,clear_condition:values.clear,xp:values.xp,quadrant:values.quadrant,updated_at:new Date().toISOString()}).eq('id',q.id).eq('user_id',session.user.id));if(!error)Object.assign(q,values)}else{const patch={subject:values.subject,task_name:values.name,task_time:values.time,clear_condition:values.clear,xp:values.xp,quadrant:values.quadrant};({error}=await db.from('task_overrides').upsert(fixedOverrideRow(q,patch)));if(!error)overrides[q.id]={...(overrides[q.id]||{}),...patch}}setSyncing(false);if(error){showToast('修改失敗，請再試一次',true);return}document.getElementById('questDialog').close();render();showToast('任務修改已同步');return}const row={user_id:session.user.id,task_date:iso(selected),subject:values.subject,title:values.name,start_time:values.time,clear_condition:values.clear,xp:values.xp,quadrant:values.quadrant,completed:false};const {data:created,error}=await db.from('custom_tasks').insert(row).select().single();setSyncing(false);if(error){showToast('新增失敗，請再試一次',true);return}customQuests.push(normalizeCustom(created));document.getElementById('questDialog').close();render();showToast('新關卡已加入！')}
async function saveSettings(event){event.preventDefault();const data=new FormData(event.currentTarget),next={headline:String(data.get('headline')).trim().slice(0,80)||'with great power comes great responsibility',theme:String(data.get('theme'))};setSyncing(true);const {error}=await db.from('profiles').update({...next,updated_at:new Date().toISOString()}).eq('user_id',session.user.id);setSyncing(false);if(error){showToast('設定儲存失敗',true);return}profile={...profile,...next};document.getElementById('settingsDialog').close();render();showToast('個人風格已儲存')}
function registerWebMCP(){const c=document.modelContext;if(!c?.registerTool)return;c.registerTool({name:'get_today_study_missions',title:'讀取今日任務',description:'取得目前選取日期的讀書任務與完成狀態。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>({date:iso(selected),missions:missionsFor(selected).map(q=>({id:q.id,subject:q.subject,title:q.name,status:q.completed?'completed':'pending',quadrant:q.quadrant,xp:q.xp}))})})}
async function bootstrap(){wireUi();registerWebMCP();const {data:{session:initial}}=await db.auth.getSession();await handleSession(initial);db.auth.onAuthStateChange((_event,next)=>setTimeout(()=>handleSession(next),0))}
bootstrap();
